SELECT CASE WHEN departments.budget >= 3508000 THEN 'high' WHEN departments.budget >= 1855000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS row_count FROM employees INNER JOIN departments ON employees.dept_id = departments.id WHERE departments.dept_name IN ('Marketing', 'Finance') GROUP BY CASE WHEN departments.budget >= 3508000 THEN 'high' WHEN departments.budget >= 1855000 THEN 'mid' ELSE 'low' END HAVING row_count > 2 ORDER BY budget_bucket LIMIT 5
